<?php

declare(strict_types=1);
function administrator_academics_input(array $input, string $type): array { if ($type === 'faculty') return [required_string($input, 'name', 200), required_string($input, 'code', 30), optional_string($input, 'dean_email', 255)]; if ($type === 'department') return [required_integer($input, 'faculty_id', 1, PHP_INT_MAX), required_string($input, 'name', 200), optional_string($input, 'code', 30)]; return [required_integer($input, 'department_id', 1, PHP_INT_MAX), required_integer($input, 'education_level_id', 1, PHP_INT_MAX), optional_string($input, 'programme_code', 50) ?? optional_string($input, 'code', 50), required_string($input, 'programme_name', 250)]; }
function list_administrator_faculties(): never { require_administrator(); $c=database_connection(); $s=$c->prepare('SELECT f.*, COUNT(DISTINCT d.department_id) AS department_count FROM faculties f LEFT JOIN departments d ON d.faculty_id=f.faculty_id GROUP BY f.faculty_id ORDER BY f.name');$s->execute();$r=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();json_success('Faculties retrieved successfully.',$r); }
function create_administrator_faculty(): never { require_administrator(); [$name,$code,$email]=administrator_academics_input(request_json_body(),'faculty');$c=database_connection();$s=$c->prepare('INSERT INTO faculties (name,code,dean_email) VALUES (?,?,?)');$s->bind_param('sss',$name,$code,$email);$s->execute();$id=$c->insert_id;$s->close();json_success('Faculty created successfully.',['faculty_id'=>$id],201); }
function update_administrator_faculty(int $id): never { require_administrator(); [$name,$code,$email]=administrator_academics_input(request_json_body(),'faculty');$c=database_connection();$s=$c->prepare('UPDATE faculties SET name=?,code=?,dean_email=? WHERE faculty_id=?');$s->bind_param('sssi',$name,$code,$email,$id);$s->execute();$n=$s->affected_rows;$s->close();if($n===0)json_error('Faculty not found or unchanged.',[],404);json_success('Faculty updated successfully.'); }
function delete_administrator_faculty(int $id): never { require_administrator();$c=database_connection();if(administrator_count($c,'SELECT COUNT(*) AS total FROM departments d INNER JOIN programmes p ON p.department_id=d.department_id WHERE d.faculty_id=?','i',[$id])>0)json_error('Faculty cannot be deleted because it is linked to programmes.',[],409);if(administrator_count($c,'SELECT COUNT(*) AS total FROM departments WHERE faculty_id=?','i',[$id])>0)json_error('Faculty cannot be deleted because it has departments.',[],409);$s=$c->prepare('DELETE FROM faculties WHERE faculty_id=?');$s->bind_param('i',$id);$s->execute();$n=$s->affected_rows;$s->close();if($n===0)json_error('Faculty not found.',[],404);json_success('Faculty deleted successfully.'); }
function list_administrator_departments(): never { require_administrator();$c=database_connection();$s=$c->prepare('SELECT d.*,f.name AS faculty_name,COUNT(p.programme_id) AS programme_count FROM departments d INNER JOIN faculties f ON f.faculty_id=d.faculty_id LEFT JOIN programmes p ON p.department_id=d.department_id GROUP BY d.department_id ORDER BY f.name,d.name');$s->execute();$r=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();json_success('Departments retrieved successfully.',$r); }
function administrator_faculty_exists(mysqli $c,int $faculty):void{$s=$c->prepare('SELECT faculty_id FROM faculties WHERE faculty_id=? LIMIT 1');$s->bind_param('i',$faculty);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();if(!is_array($r))json_error('Faculty not found.',[],422);}
function create_administrator_department(): never {require_administrator();[$faculty,$name,$code]=administrator_academics_input(request_json_body(),'department');$c=database_connection();administrator_faculty_exists($c,$faculty);$s=$c->prepare('INSERT INTO departments (faculty_id,name,code) VALUES (?,?,?)');$s->bind_param('iss',$faculty,$name,$code);$s->execute();$id=$c->insert_id;$s->close();json_success('Department created successfully.',['department_id'=>$id],201);}
function update_administrator_department(int $id): never {require_administrator();[$faculty,$name,$code]=administrator_academics_input(request_json_body(),'department');$c=database_connection();administrator_faculty_exists($c,$faculty);$s=$c->prepare('UPDATE departments SET faculty_id=?,name=?,code=? WHERE department_id=?');$s->bind_param('issi',$faculty,$name,$code,$id);$s->execute();$n=$s->affected_rows;$s->close();if($n===0)json_error('Department not found or unchanged.',[],404);json_success('Department updated successfully.');}
function delete_administrator_department(int $id): never {require_administrator();$c=database_connection();if(administrator_count($c,'SELECT COUNT(*) AS total FROM programmes WHERE department_id=?','i',[$id])>0)json_error('Department cannot be deleted because it is linked to programmes.',[],409);$s=$c->prepare('DELETE FROM departments WHERE department_id=?');$s->bind_param('i',$id);$s->execute();$n=$s->affected_rows;$s->close();if($n===0)json_error('Department not found.',[],404);json_success('Department deleted successfully.');}
function list_administrator_programmes(): never {require_administrator();$c=database_connection();$s=$c->prepare('SELECT p.*,d.name AS department_name,f.name AS faculty_name,el.name AS education_level_name FROM programmes p INNER JOIN departments d ON d.department_id=p.department_id INNER JOIN faculties f ON f.faculty_id=d.faculty_id INNER JOIN education_levels el ON el.education_level_id=p.education_level_id ORDER BY f.name,d.name,p.name');$s->execute();$r=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();json_success('Programmes retrieved successfully.',$r);}
function administrator_programme_dependencies(mysqli $c,int $department,int $level):void{$s=$c->prepare('SELECT department_id FROM departments WHERE department_id=?');$s->bind_param('i',$department);$s->execute();$d=$s->get_result()->fetch_assoc();$s->close();if(!is_array($d))json_error('Department not found.',[],422);$s=$c->prepare('SELECT education_level_id FROM education_levels WHERE education_level_id=? AND is_active=1');$s->bind_param('i',$level);$s->execute();$l=$s->get_result()->fetch_assoc();$s->close();if(!is_array($l))json_error('Education level not found.',[],422);}
function create_administrator_programme(): never {require_administrator();[$department,$level,$code,$name]=administrator_academics_input(request_json_body(),'programme');$c=database_connection();administrator_programme_dependencies($c,$department,$level);$s=$c->prepare('INSERT INTO programmes (department_id,education_level_id,code,name) VALUES (?,?,?,?)');$s->bind_param('iiss',$department,$level,$code,$name);$s->execute();$id=$c->insert_id;$s->close();json_success('Programme created successfully.',['programme_id'=>$id],201);}
function update_administrator_programme(int $id): never {require_administrator();[$department,$level,$code,$name]=administrator_academics_input(request_json_body(),'programme');$c=database_connection();administrator_programme_dependencies($c,$department,$level);$s=$c->prepare('UPDATE programmes SET department_id=?,education_level_id=?,code=?,name=? WHERE programme_id=?');$s->bind_param('iissi',$department,$level,$code,$name,$id);$s->execute();$n=$s->affected_rows;$s->close();if($n===0)json_error('Programme not found or unchanged.',[],404);json_success('Programme updated successfully.');}
function delete_administrator_programme(int $id): never {require_administrator();$c=database_connection();if(administrator_count($c,'SELECT COUNT(*) AS total FROM graduate_qualifications WHERE programme_id=?','i',[$id])>0)json_error('Programme cannot be deleted because graduates are linked to it.',[],409);$s=$c->prepare('DELETE FROM programmes WHERE programme_id=?');$s->bind_param('i',$id);$s->execute();$n=$s->affected_rows;$s->close();if($n===0)json_error('Programme not found.',[],404);json_success('Programme deleted successfully.');}
